import java.util.*;

class Solution {
    public boolean parseBoolExpr(String expression) {
        Deque<Character> stack = new ArrayDeque<>();
        for (char c : expression.toCharArray()) {
            if (c == ',') {
                continue;
            }
            if (c != ')') {
                stack.push(c);
                continue;
            }

            boolean hasTrue = false;
            boolean hasFalse = false;
            while (stack.peek() != '(') {
                char value = stack.pop();
                hasTrue |= value == 't';
                hasFalse |= value == 'f';
            }
            stack.pop();
            char operator = stack.pop();
            stack.push(reduce(operator, hasTrue, hasFalse) ? 't' : 'f');
        }
        return stack.peek() == 't';
    }

    private boolean reduce(char operator, boolean hasTrue, boolean hasFalse) {
        if (operator == '!') {
            return !hasTrue;
        }
        if (operator == '&') {
            return !hasFalse;
        }
        return hasTrue;
    }
}

class Solution {
    private int index;

    public boolean parseBoolExpr(String expression) {
        index = 0;
        return parse(expression);
    }

    private boolean parse(String expression) {
        char token = expression.charAt(index);
        if (token == 't') {
            index++;
            return true;
        }
        if (token == 'f') {
            index++;
            return false;
        }

        char operator = token;
        index += 2;
        if (operator == '!') {
            boolean value = !parse(expression);
            index++;
            return value;
        }

        boolean result = operator == '&';
        boolean first = true;
        while (expression.charAt(index) != ')') {
            if (expression.charAt(index) == ',') {
                index++;
                continue;
            }
            boolean value = parse(expression);
            if (first) {
                result = value;
                first = false;
            } else if (operator == '&') {
                result &= value;
            } else {
                result |= value;
            }
        }
        index++;
        return result;
    }
}

import java.util.*;

class Solution {
    public boolean parseBoolExpr(String expression) {
        Deque<Frame> frames = new ArrayDeque<>();
        char pendingOperator = 0;
        boolean result = false;

        for (int i = 0; i < expression.length(); i++) {
            char token = expression.charAt(i);
            if (token == '&' || token == '|' || token == '!') {
                pendingOperator = token;
            } else if (token == '(') {
                frames.push(new Frame(pendingOperator));
                pendingOperator = 0;
            } else if (token == 't' || token == 'f') {
                result = token == 't';
                if (!frames.isEmpty()) {
                    frames.peek().add(result);
                }
            } else if (token == ')') {
                result = frames.pop().value();
                if (!frames.isEmpty()) {
                    frames.peek().add(result);
                }
            }
        }
        return result;
    }

    private static final class Frame {
        private final char operator;
        private boolean hasTrue;
        private boolean hasFalse;

        Frame(char operator) {
            this.operator = operator;
        }

        void add(boolean value) {
            hasTrue |= value;
            hasFalse |= !value;
        }

        boolean value() {
            if (operator == '!') {
                return !hasTrue;
            }
            if (operator == '&') {
                return !hasFalse;
            }
            return hasTrue;
        }
    }
}

class Solution {
    private int index;

    public boolean parseBoolExpr(String expression) {
        index = 0;
        return parse(expression);
    }

    private boolean parse(String expression) {
        char token = expression.charAt(index);
        if (token == 't') {
            index++;
            return true;
        }
        if (token == 'f') {
            index++;
            return false;
        }

        char operator = token;
        index += 2;
        if (operator == '!') {
            boolean value = !parse(expression);
            index++;
            return value;
        }

        boolean answer = operator == '&';
        boolean decided = false;
        while (expression.charAt(index) != ')') {
            if (expression.charAt(index) == ',') {
                index++;
                continue;
            }
            if (decided) {
                skipExpression(expression);
                continue;
            }
            boolean value = parse(expression);
            if (operator == '&' && !value) {
                answer = false;
                decided = true;
            } else if (operator == '|' && value) {
                answer = true;
                decided = true;
            } else {
                answer = value;
            }
        }
        index++;
        return answer;
    }

    private void skipExpression(String expression) {
        char token = expression.charAt(index);
        if (token == 't' || token == 'f') {
            index++;
            return;
        }
        index += 2;
        int depth = 1;
        while (depth > 0) {
            char current = expression.charAt(index++);
            if (current == '(') {
                depth++;
            } else if (current == ')') {
                depth--;
            }
        }
    }
}

class Solution {
    public boolean parseBoolExpr(String expression) {
        int n = expression.length();
        char[] operators = new char[n];
        int[] masks = new int[n];
        int top = -1;
        char pendingOperator = 0;
        boolean result = false;

        for (int i = 0; i < n; i++) {
            char token = expression.charAt(i);
            if (token == '&' || token == '|' || token == '!') {
                pendingOperator = token;
            } else if (token == '(') {
                top++;
                operators[top] = pendingOperator;
                masks[top] = 0;
                pendingOperator = 0;
            } else if (token == 't' || token == 'f') {
                result = token == 't';
                if (top >= 0) {
                    masks[top] |= result ? 2 : 1;
                }
            } else if (token == ')') {
                result = reduce(operators[top], masks[top]);
                top--;
                if (top >= 0) {
                    masks[top] |= result ? 2 : 1;
                }
            }
        }
        return result;
    }

    private boolean reduce(char operator, int mask) {
        if (operator == '!') {
            return (mask & 2) == 0;
        }
        if (operator == '&') {
            return (mask & 1) == 0;
        }
        return (mask & 2) != 0;
    }
}
